import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "./useAuth";

export interface AppNotification {
  id: string;
  category: "order" | "other";
  type: string;
  title: string;
  body: string | null;
  link_url: string | null;
  read_at: string | null;
  created_at: string;
}

// Two-area notification center: "order" (new order, cancellation, return,
// vendor confirmation, unconfirmed reminder - all generated by DB
// triggers/a cron job, see the notifications migration) and "other" (a
// general bucket, wired and ready, currently unpopulated). Polls rather
// than using Supabase Realtime - simplest reliable way to get "visible
// without an extra click" without adding a new moving part this pass.
//
// One shared query for every bell and banner on the page (the header alone
// has two), every 2 minutes, only while the tab is in front - react-query
// skips background polls and refetches when the tab gets focus again.
const POLL_MS = 2 * 60 * 1000;

export function useNotifications() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ["notifications", user?.id ?? null];

  const { data: notifications = [], isLoading, refetch } = useQuery({
    queryKey,
    enabled: !!user,
    refetchInterval: POLL_MS,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("notifications")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(50);
      if (error) throw error;
      return (data ?? []) as AppNotification[];
    },
  });

  const showRead = (ids: string[], now: string) =>
    queryClient.setQueryData<AppNotification[]>(queryKey, (prev) =>
      prev?.map((n) => (ids.includes(n.id) ? { ...n, read_at: now } : n)),
    );

  const markRead = async (id: string) => {
    const now = new Date().toISOString();
    showRead([id], now);
    await supabase.from("notifications").update({ read_at: now }).eq("id", id);
  };

  const markAllRead = async (category: "order" | "other") => {
    const now = new Date().toISOString();
    const ids = notifications.filter((n) => n.category === category && !n.read_at).map((n) => n.id);
    if (ids.length === 0) return;
    showRead(ids, now);
    await supabase.from("notifications").update({ read_at: now }).in("id", ids);
  };

  const orderNotifications = notifications.filter((n) => n.category === "order");
  const otherNotifications = notifications.filter((n) => n.category === "other");

  return {
    orderNotifications,
    otherNotifications,
    unreadOrderCount: orderNotifications.filter((n) => !n.read_at).length,
    unreadOtherCount: otherNotifications.filter((n) => !n.read_at).length,
    markRead,
    markAllRead,
    loading: isLoading,
    refetch,
  };
}
